window.CARDS=window.CARDS||{};CARDS["people-hoshinomiya-chie"]=[{"i":"sc-hoshinomiya-chie-y1v1-p139-1","v":"y1v1","y":1,"o":1,"k":"action spoken","w":"chabashira-sae ayanokouji-kiyotaka hoshinomiya-chie","q":"hoshinomiya chie hallway flirtation   history with chabashira class 1 b homeroom teacher  hallway outside faculty staff room  inspecting her makeup appearance in a mirror when ayanokoji calls out seeking chabashira  wavy  shoulder length hair  mature looks  bubbly student like demeanor   hmm  sae chan  oh  she was just here a moment ago  follows ayanokoji into the hallway when he steps outside to wait  barrages him with inquisitive  overly familiar questions   i m hoshinomiya chie  in charge of class b  sae and i have been best friends since high school  that s why we call each other sae chan and chie chan   hey  why did sae chan call you  huh  huh  why  i don t understand  you were called to the office without a reason  hmm  what s your name   ayanokouji kun  huh  oh  wow  that s a cool name  you re pretty popular  aren t you  hey  do you already have a girlfriend  clings onto ayanokoji  grabbing his arms with slender hands and caressing his cheek in playful flirtation   hmm  how unexpected  if we were in the same class  i d never leave you alone  perhaps because you re so innocent  or do you like playing hard to get  smacked over the head with a clipboard when chabashira appears  whines and playfully teases chabashira about her motives   ouch  what was that for   i was only keeping him company while he waited for you  sae chan   come on  don t be so cold  it won t be the end of the world if i listen  right  besides sae chan  you re definitely not the type to give one on one guidance  pulling a new student like ayanokouji kun into the guidance room out of nowhere  are you after something  i wonder   so  sae chan  are you looking to be dominated by a younger man  hee  you re certainly right  it wouldn t be possible for you  sae chan  whacked on the butt by chabashira s clipboard  scurries off with ichinose honami  high school classmates   lifelong friends with chabashira sae  attracted to graduates of anhs s competitive system  shamelessly flirtatious  bubbly  emotionally perceptive  uses playful intimacy to prod into other classes  affairs  high school best friends  intimate rivalrous banter  sae chan and chie chan  first encounter  singles him out for physical teasing and probing","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v1-p139-1\"><h3><span class=\"ttl\">Hallway flirtation &amp; history with Chabashira<\/span><span class=\"meta\">Y1V1 · p.139–141<\/span><\/h3><p class=\"setup\">Hallway outside faculty staff room.<\/p><p class=\"with\">with <a href=\"chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hmm? Sae-chan? Oh, she was just here a moment ago.”<span class=\"pg\">p.139<\/span><\/li><li class=\"q spoken\">“I’m Hoshinomiya Chie, in charge of Class B. Sae and I have been best friends since high school. That’s why we call each other Sae-chan and Chie-chan.”<span class=\"pg\">p.140<\/span><\/li><li class=\"q spoken\">“Hey, why did Sae-chan call you? Huh? Huh? Why?… I don’t understand. You were called to the office without a reason? Hmm? What’s your name?”<span class=\"pg\">p.140<\/span><\/li><\/ul><details class=\"more\"><summary>16 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Post<\/span> Class 1-B homeroom teacher.<span class=\"pg\">p.140–141<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Inspecting her makeup/appearance in a mirror when Ayanokōji calls out seeking Chabashira. Wavy, shoulder-length hair, mature looks, bubbly student-like demeanor.<span class=\"pg\">p.139<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Follows Ayanokōji into the hallway when he steps outside to wait; barrages him with inquisitive, overly familiar questions.<span class=\"pg\">p.139–140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokouji-kun, huh? Oh, wow, that’s a cool name. You’re pretty popular, aren’t you?… Hey, do you already have a girlfriend?”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Clings onto Ayanokōji, grabbing his arms with slender hands and caressing his cheek in playful flirtation.<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm? How unexpected. If we were in the same class, I’d never leave you alone. Perhaps because you’re so innocent? Or do you like playing hard to get?”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Smacked over the head with a clipboard when Chabashira appears; whines and playfully teases Chabashira about her motives.<span class=\"pg\">p.140–141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ouch! What was that for?”<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I was only keeping him company while he waited for you, Sae-chan.”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Come on, don’t be so cold! It won’t be the end of the world if I listen, right? Besides Sae-chan, you’re definitely not the type to give one-on-one guidance. Pulling a new student like Ayanokouji-kun into the guidance room out of nowhere… Are you after something, I wonder?”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, Sae-chan, are you looking to be dominated by a younger man?… Hee, you’re certainly right. It wouldn’t be possible for you, Sae-chan.”<span class=\"pg\">p.141<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Whacked on the butt by Chabashira&#x27;s clipboard; scurries off with Ichinose Honami.<span class=\"pg\">p.141–142<\/span><\/li><li><span class=\"mlabel\">Backstory<\/span> High school classmates &amp; lifelong friends with Chabashira Sae (attracted to/graduates of ANHS&#x27;s competitive system).<span class=\"pg\">p.140<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Shamelessly flirtatious, bubbly, emotionally perceptive; uses playful intimacy to prod into other classes&#x27; affairs.<span class=\"pg\">p.139–141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> High school best friends; intimate rivalrous banter (&quot;Sae-chan and Chie-chan&quot;).<span class=\"pg\">p.140–141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> First encounter: singles him out for physical teasing and probing.<span class=\"pg\">p.140<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v1-p226-1\">→ After: The faculty-room smile<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v1-p226-1","v":"y1v1","y":1,"o":1,"k":"action","w":"hoshinomiya-chie","q":"hoshinomiya chie the faculty room smile seated in the faculty room during the test change confrontation  meets ayanokoji s eyes and gives a small smile and a wave   the only teacher besides chabashira to react at all to the incident","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v1-p226-1\"><h3><span class=\"ttl\">The faculty-room smile<\/span><span class=\"meta\">Y1V1 · p.226<\/span><\/h3><ul class=\"lines\"><li class=\"q action\">Seated in the faculty room during the test-change confrontation; meets Ayanokōji&#x27;s eyes and gives a small smile and a wave — the only teacher besides Chabashira to react at all to the incident.<span class=\"pg\">p.226<\/span><\/li><\/ul><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v1-p139-1\">← Before: Hallway flirtation &amp; history with Chabashira<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v2-p191-1","v":"y1v2","y":1,"o":2,"k":"spoken","w":"hoshinomiya-chie","q":"hoshinomiya chie ch 6 open  the teacher at the door the faculty room minutes before the hearing  she greets the four class d students as they arrive   yahoo  hello  class d students   it seems like something rather incredible has happened  hmm  her interest is appetite  not concern   her eyes sparkled  as if she enjoyed sticking her nose into other people s business  the narrator adds  in parentheses   well  she did   oh no  i ve been found out already  huh   so i guess i can t join in  huh   aw  that s too bad  well  that s all right  the results should be out within the hour  i guess  she knows the hearing schedule before it starts and expects a result inside the hour  chabashira pushes her back into the faculty room before she can say more  her exclusion states the rule from the outside   outsiders cannot participate  in a disciplinary settlement","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v2-p191-1\"><h3><span class=\"ttl\">Ch.6 open: the teacher at the door<\/span><span class=\"meta\">Y1V2 · p.191–192<\/span><\/h3><p class=\"setup\">The faculty room minutes before the hearing; she greets the four Class D students as they arrive.<\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;Yahoo! Hello, Class D students!&quot;<span class=\"pg\">p.191<\/span><\/li><li class=\"q spoken\">&quot;It seems like something rather incredible has happened, hmm?&quot;<span class=\"pg\">p.191<\/span><\/li><li class=\"q spoken\">&quot;Oh no. I’ve been found out already, huh?&quot;<span class=\"pg\">p.192<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Her interest is appetite, not concern: &quot;Her eyes sparkled, as if she enjoyed sticking her nose into other people’s business.&quot; The narrator adds, in parentheses, &quot;(Well, she did).&quot;<span class=\"pg\">p.191<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;So I guess I can’t join in, huh?&quot;<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Aw, that’s too bad. Well, that’s all right. The results should be out within the hour, I guess.&quot;<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She knows the hearing schedule before it starts and expects a result inside the hour; Chabashira pushes her back into the faculty room before she can say more.<span class=\"pg\">p.192<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Her exclusion states the rule from the outside: &quot;outsiders cannot participate&quot; in a disciplinary settlement.<span class=\"pg\">p.192<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hoshinomiya-chie-y1v3-p36-1","v":"y1v3","y":1,"o":3,"k":"spoken","w":"chabashira-sae ayanokouji-kiyotaka hoshinomiya-chie","q":"hoshinomiya chie ch 2 sec  2 1  the corridor ambush beach side  during class d s rules huddle  she tackles chabashira from behind   what  i can t be friendly  i honestly wanted to see what you d do     whenever i touch your hair  sae chan  it s always so smooth  gets the eavesdropping rebuke and the  fate  double meaning ignored  leaves with a sad look when threatened with a behavioural report  spots him and opens the summer love advice    summer is the season of love  if you want to confess your feelings to a girl you like  perhaps it d be more effective while standing before the beautiful ocean    to his visible embarrassment   you need to be more carefree","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v3-p36-1\"><h3><span class=\"ttl\">Ch.2 sec. 2.1: the corridor ambush<\/span><span class=\"meta\">Y1V3 · p.36–38<\/span><\/h3><p class=\"setup\">Beach-side, during Class D&#x27;s rules huddle; she tackles Chabashira from behind.<\/p><p class=\"with\">with <a href=\"chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“What, I can’t be friendly? I honestly wanted to see what you’d do.” / “Whenever I touch your hair, Sae-chan, it’s always so smooth!”<span class=\"pg\">p.36<\/span><\/li><li class=\"q spoken\">“You need to be more carefree!”<span class=\"pg\">p.38<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Gets the eavesdropping rebuke and the &quot;fate&quot; double-meaning ignored; leaves with a sad look when threatened with a behavioural report.<span class=\"pg\">p.38<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Spots him and opens the summer-love advice — &quot;Summer is the season of love. If you want to confess your feelings to a girl you like, perhaps it’d be more effective while standing before the beautiful ocean?&quot; — to his visible embarrassment.<span class=\"pg\">p.38<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hoshinomiya-chie-y1v4-p121-1","v":"y1v4","y":1,"o":4,"k":"action spoken","w":"ichinose-honami chabashira-sae mashima-tomonari sakagami ryuuen-kakeru ayanokouji-kiyotaka hoshinomiya-chie","q":"hoshinomiya chie ch 3 sec  3 6  the class b homeroom at the sofa with chabashira and mashima at the first level vending machines  she drinks whiskey neat  owns the ichinose to rabbit move  and is ordered to stop spying   ah ha ha  we broke up two weeks ago  i m the type of girl who breaks it off once the relationship starts getting serious  it s just like  see ya later  hoshinomiya sensei said  also addresses mashima as  mashima kun  and is called  chie  back  most of the date talk lines are untagged   recorded on the volume attribution list  pours whiskey into an empty glass and downs it in one gulp    must ve been a drinker   huh  what are you talking about  what d i do   the answer to  what are you planning  chie    speaker of the question untagged   i m not screwing around or anything  it s certainly true that as far as grades and attitude are concerned  ichinose san is number one  however  someone s true place in society cannot be measured by numbers alone  i determined that she needed a challenge  and besides  rabbits are just so cute  aren t they  the way they hop around  doesn t that suit ichinose san  hoshinomiya sensei asked   oh  are you still talking about what happened ten years ago  i thought that was all water under the bridge   the ten year grudge  speaker untagged in the exchange   recorded under her as the chie being addressed   note  keeps the gap   i genuinely thought that ichinose needed to learn a lesson  so i removed her from the dragon group  you know  by the way  sae chan  i couldn t help but notice you ve been focusing on ayanokouji kun  anyway  it s just a coincidence  coincidence  coincidence  when the island test ended and ayanokouji kun became a kind of leader  you weren t surprised at all  were you   agh  it s like you don t trust me at all  well  i m not the only one to blame  sakagami sensei is part of the problem  too  if we evaluated the class c students properly  another student should ve been placed into dragon  but they threw ryuuen in there  admits she is watching ayanokoji   the reconnaissance ayanokoji files as  apparently i was under heavy scrutiny  the class b student she deliberately kept out of dragon and put in rabbit   sae chan    the focus of her  coincidence  needle  ordered to stop spying on colleagues  classes  named as part of the class c evaluation problem  the class c student  they threw  into dragon  the student she has been watching since the island endgame","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v4-p121-1\"><h3><span class=\"ttl\">Ch.3 sec. 3.6: the Class B homeroom at the sofa<\/span><span class=\"meta\">Y1V4 · p.121–123<\/span><\/h3><p class=\"setup\">With Chabashira and Mashima at the first-level vending machines, she drinks whiskey neat, owns the Ichinose-to-Rabbit move, and is ordered to stop spying.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"mashima-tomonari.html\">Mashima Tomonari<\/a> · <a href=\"sakagami.html\">Sakagami<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ah ha ha! We broke up two weeks ago. I’m the type of girl who breaks it off once the relationship starts getting serious. It’s just like, see ya later!” Hoshinomiya-sensei said.<span class=\"pg\">p.121<\/span><\/li><li class=\"q spoken\">“Huh? What are you talking about? What’d I do?” (the answer to “What are you planning, Chie?” — speaker of the question untagged)<span class=\"pg\">p.122<\/span><\/li><li class=\"q spoken\">“I’m not screwing around or anything. It’s certainly true that as far as grades and attitude are concerned, Ichinose-san is number one. However, someone’s true place in society cannot be measured by numbers alone. I determined…”<span class=\"pg\">p.122<\/span><\/li><\/ul><details class=\"more\"><summary>13 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Also addresses Mashima as “Mashima-kun” and is called “Chie” back; most of the date-talk lines are untagged — recorded on the volume attribution list.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Pours whiskey into an empty glass and downs it in one gulp — “Must’ve been a drinker.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m not screwing around or anything. It’s certainly true that as far as grades and attitude are concerned, Ichinose-san is number one. However, someone’s true place in society cannot be measured by numbers alone. I determined that she needed a challenge. And besides, rabbits are just so cute, aren’t they? The way they hop around. Doesn’t that suit Ichinose-san?” Hoshinomiya-sensei asked.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Oh, are you still talking about what happened ten years ago? I thought that was all water under the bridge.” (the ten-year grudge, speaker untagged in the exchange — recorded under her as the Chie being addressed; [note] keeps the gap)<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I genuinely thought that Ichinose needed to learn a lesson, so I removed her from the Dragon group. You know? By the way, Sae-chan, I couldn’t help but notice you’ve been focusing on Ayanokouji-kun. Anyway, it’s just a coincidence. Coincidence, coincidence. When the island test ended and Ayanokouji-kun became a kind of leader, you weren’t surprised at all, were you?”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Agh, it’s like you don’t trust me at all. Well, I’m not the only one to blame. Sakagami-sensei is part of the problem, too. If we evaluated the Class C students properly, another student should’ve been placed into Dragon. But they threw Ryuuen in there.”<span class=\"pg\">p.122–123<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Admits she is watching Ayanokōji — the reconnaissance Ayanokōji files as “Apparently I was under heavy scrutiny.”<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> The Class B student she deliberately kept out of Dragon and put in Rabbit.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> “Sae-chan” — the focus of her “coincidence” needle.<span class=\"pg\">p.121–122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Ordered to stop spying on colleagues’ classes.<span class=\"pg\">p.122<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakagami<\/b> Named as part of the Class C evaluation problem.<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> The Class C student “they threw” into Dragon.<span class=\"pg\">p.123<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> The student she has been watching since the island endgame.<span class=\"pg\">p.122<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v4-p125-1\">→ After: Ch.4 sec. 4.0: the spy order in the brief<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v4-p125-1","v":"y1v4","y":1,"o":4,"k":"","w":"ichinose-honami hoshinomiya-chie","q":"hoshinomiya chie ch 4 sec  4 0  the spy order in the brief named only as the teacher who secretly sent ichinose and the class b trio to watch ayanokoji   his private inventory of problems for the day  the class b three in the rabbit group are filed as her agents on him  not as random group mates  no scene presence this range  the row records the brief s attribution of the spy order","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v4-p125-1\"><h3><span class=\"ttl\">Ch.4 sec. 4.0: the spy order in the brief<\/span><span class=\"meta\">Y1V4 · p.125<\/span><\/h3><p class=\"setup\">Named only as the teacher who secretly sent Ichinose and the Class B trio to watch Ayanokōji — his private inventory of problems for the day.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> The Class B three in the Rabbit group are filed as her agents on him, not as random group-mates.<span class=\"pg\">p.125<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No scene presence this range; the row records the brief’s attribution of the spy order.<span class=\"pg\">p.125<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v4-p121-1\">← Before: Ch.3 sec. 3.6: the Class B homeroom at the sofa<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v4-p167-1\">→ After: Ch.4 sec. 4.3: the drunk interruption<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v4-p167-1","v":"y1v4","y":1,"o":4,"k":"spoken","w":"ayanokouji-kiyotaka chabashira-sae ichinose-honami hoshinomiya-chie","q":"hoshinomiya chie ch 4 sec  4 3  the drunk interruption follows chabashira to the night pool  hugs ayanokoji smelling of alcohol  baits the private meeting as suspicious  and leaves with a  no sexy times  shot   yoohoo  sae chan  how you feeling   hmm  oh no  of course i m not  i m not drunk  i was just acting all sleepy  you know  iron liver   handled herself today and still fine   acting all sleepy  denied drunk to chabashira s face   jeez  you can really hold your liquor   chabashira s line  tagged in exchange   good evening  ayanokouji kun  how are you doing   that answer was so not cute that i m impressed  so  ayanokouji kun  do you love the tsuntsun older sister types  like sae chan  asked hoshinomiya sensei  hand on his shoulders  a tight hug  alcohol smell   overly familiar by design  the night pool chase  baits her on sneaking around  gets the  ayanokouji requested this location  answer  mutters no rules broken  exits under  hurry up and leave   so what were you two talking about in the middle of the night  isn t that in itself a really big problem  asked hoshinomiya sensei   if that s true  wouldn t it be better for you to do it with more people around  if you look like you re sneaking around  i can t help but think it s suspicious   hmm  well  i suppose you re not violating any rules  muttered hoshinomiya sensei   okay  okay  but remember  no sexy times  teased hoshinomiya sensei  bad at hiding emotions   his read that ichinose may soon wonder why she is in rabbit and discover the spy order  followed chabashira deliberately   was it just a coincidence  unlikely","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v4-p167-1\"><h3><span class=\"ttl\">Ch.4 sec. 4.3: the drunk interruption<\/span><span class=\"meta\">Y1V4 · p.167–168<\/span><\/h3><p class=\"setup\">Follows Chabashira to the night pool, hugs Ayanokōji smelling of alcohol, baits the private meeting as suspicious, and leaves with a “no sexy times” shot.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Yoohoo, Sae-chan! How you feeling?”<span class=\"pg\">p.167<\/span><\/li><li class=\"q spoken\">“Hmm? Oh no, of course I’m not, I’m not drunk. I was just acting all sleepy, you know?”<span class=\"pg\">p.167<\/span><\/li><li class=\"q spoken\">“Jeez. You can really hold your liquor.” (Chabashira’s line, tagged in exchange)<span class=\"pg\">p.167<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Iron liver — handled herself today and still fine; “acting all sleepy” denied drunk to Chabashira’s face.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Good evening, Ayanokouji-kun. How are you doing?”<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That answer was so not-cute that I’m impressed! So, Ayanokouji-kun, do you love the tsuntsun older sister types, like Sae-chan?” asked Hoshinomiya-sensei.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Hand on his shoulders, a tight hug, alcohol smell — overly familiar by design.<span class=\"pg\">p.167<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> The night-pool chase: baits her on sneaking around, gets the “Ayanokouji requested this location” answer, mutters no rules broken, exits under “hurry up and leave.”<span class=\"pg\">p.167-168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So what were you two talking about in the middle of the night? Isn’t that in itself a really big problem?” asked Hoshinomiya-sensei.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If that’s true, wouldn’t it be better for you to do it with more people around? If you look like you’re sneaking around, I can’t help but think it’s suspicious.”<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hmm. Well, I suppose you’re not violating any rules,” muttered Hoshinomiya-sensei.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Okay, okay. But remember, no sexy times,” teased Hoshinomiya-sensei.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Bad at hiding emotions — his read that Ichinose may soon wonder why she is in Rabbit and discover the spy order.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Followed Chabashira deliberately; “Was it just a coincidence? Unlikely.”<span class=\"pg\">p.167<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v4-p125-1\">← Before: Ch.4 sec. 4.0: the spy order in the brief<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v4-p169-1\">→ After: Ch.4: walking away<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v4-p169-1","v":"y1v4","y":1,"o":4,"k":"","w":"hoshinomiya-chie","q":"hoshinomiya chie ch 4  walking away the night pool encounter ends  he leaves in the direction opposite hers  ayanokoji decides to leave it at that and walks away a different way from hoshinomiya sensei   good enough for the time being despite having more questions","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v4-p169-1\"><h3><span class=\"ttl\">Ch.4: walking away<\/span><span class=\"meta\">Y1V4 · p.169<\/span><\/h3><p class=\"setup\">The night-pool encounter ends; he leaves in the direction opposite hers.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Ayanokōji decides to leave it at that and walks away a different way from Hoshinomiya-sensei — good enough for the time being despite having more questions.<span class=\"pg\">p.169<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v4-p167-1\">← Before: Ch.4 sec. 4.3: the drunk interruption<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v4-p230-1\">→ After: Ch.5 sec. 5.2: the unlock authority<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v4-p230-1","v":"y1v4","y":1,"o":4,"k":"","w":"ichinose-honami ayanokouji-kiyotaka hoshinomiya-chie","q":"hoshinomiya chie ch 5 sec  5 2  the unlock authority ichinose cites her confirmation  with enough points the sim device lock releases immediately   i checked with hoshinomiya sensei to confirm  she said that with enough points  you can unlock the device right away  sim lock release is a point purchase   the loophole that makes the double swap work on a ship at sea  he had already paid for the same unlock on karuizawa s phone  named only  no scene presence","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v4-p230-1\"><h3><span class=\"ttl\">Ch.5 sec. 5.2: the unlock authority<\/span><span class=\"meta\">Y1V4 · p.230<\/span><\/h3><p class=\"setup\">Ichinose cites her confirmation: with enough points the SIM device lock releases immediately.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> “I checked with Hoshinomiya-sensei to confirm. She said that with enough points, you can unlock the device right away.”<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> SIM lock release is a point purchase — the loophole that makes the double swap work on a ship at sea.<span class=\"pg\">p.230<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He had already paid for the same unlock on Karuizawa’s phone.<span class=\"pg\">p.231<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Named only; no scene presence.<span class=\"pg\">p.230<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v4-p169-1\">← Before: Ch.4: walking away<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v4_5-p180-1","v":"y1v4.5","y":1,"o":5,"k":"","w":"hoshinomiya-chie","q":"hoshinomiya chie ch 6  a passing mention recalled in ayanokoji s memory as the teacher horikita was discussing student council business with on the day he met her  on the day he met horikita  she was talking to hoshinomiya sensei  class b s homeroom teacher  about student council business","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v4_5-p180-1\"><h3><span class=\"ttl\">Ch.6: a passing mention<\/span><span class=\"meta\">Y1V4.5 · p.180<\/span><\/h3><p class=\"setup\">Recalled in Ayanokōji&#x27;s memory as the teacher Horikita was discussing student council business with on the day he met her.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Backstory<\/span> On the day he met Horikita, she was talking to Hoshinomiya-sensei, Class B&#x27;s homeroom teacher, about student council business.<span class=\"pg\">p.180<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hoshinomiya-chie-y1v7-p73-1","v":"y1v7","y":1,"o":8,"k":"","w":"chabashira-sae hoshinomiya-chie","q":"hoshinomiya chie ch 3  the old teasing  cited old friend of chabashira  her comment about wanting to  be dominated by a younger man  is ayanokoji s key to the teacher s class a hunger  the friend who knew the hidden desire first","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v7-p73-1\"><h3><span class=\"ttl\">Ch.3: the old teasing, cited<\/span><span class=\"meta\">Y1V7 · p.73<\/span><\/h3><p class=\"with\">with <a href=\"chabashira-sae.html\">Chabashira Sae<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Old friend of Chabashira; her comment about wanting to “be dominated by a younger man” is Ayanokōji’s key to the teacher’s Class A hunger.<span class=\"pg\">p.73<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> The friend who knew the hidden desire first.<span class=\"pg\">p.73<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hoshinomiya-chie-y1v9-p8-1","v":"y1v9","y":1,"o":11,"k":"spoken","w":"ichinose-honami nagumo-miyabi hoshinomiya-chie","q":"hoshinomiya chie named as ichinose s homeroom teacher during the prologue interview  nagumo cites information obtained from ichinose s homeroom teacher  identified as ichinose s homeroom teacher  reported her entrance exam results to nagumo   i heard from your homeroom teacher  hoshinomiya sensei  looks like your results on the entrance exams were also outstanding  hoshinomiya does not appear in person  only named as the source of nagumo s information","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v9-p8-1\"><h3><span class=\"ttl\">Named as Ichinose’s homeroom teacher<\/span><span class=\"meta\">Y1V9 · p.8<\/span><\/h3><p class=\"setup\">During the prologue interview, Nagumo cites information obtained from Ichinose’s homeroom teacher.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Nagumo Miyabi<\/b> “I heard from your homeroom teacher, Hoshinomiya-sensei. Looks like your results on the entrance exams were also outstanding.”<span class=\"pg\">p.8<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Identified as Ichinose’s homeroom teacher; reported her entrance-exam results to Nagumo.<span class=\"pg\">p.8<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Hoshinomiya does not appear in person; only named as the source of Nagumo’s information.<span class=\"pg\">p.8<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v9-p180-1\">→ After: The school’s intervention<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v9-p180-1","v":"y1v9","y":1,"o":11,"k":"","w":"ichinose-honami hoshinomiya-chie","q":"hoshinomiya chie the school s intervention enters class b with nagumo and chabashira  present as class b s homeroom teacher during the intervention","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v9-p180-1\"><h3><span class=\"ttl\">The school’s intervention<\/span><span class=\"meta\">Y1V9 · p.180<\/span><\/h3><p class=\"setup\">Enters Class B with Nagumo and Chabashira.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Present as Class B’s homeroom teacher during the intervention.<span class=\"pg\">p.180<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v9-p8-1\">← Before: Named as Ichinose’s homeroom teacher<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v10-p252-1","v":"y1v10","y":1,"o":12,"k":"","w":"ichinose-honami hoshinomiya-chie","q":"hoshinomiya chie ch 6  listening to ichinose as homeroom teacher listens to ichinose speak to class b after school  she feels uneasy about the exam and worries about the class unity being damaged by an expulsion  listens as ichinose assures the class no one will be expelled","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v10-p252-1\"><h3><span class=\"ttl\">Ch.6: Listening to Ichinose<\/span><span class=\"meta\">Y1V10 · p.252–253<\/span><\/h3><p class=\"setup\">As homeroom teacher listens to Ichinose speak to Class B after school; she feels uneasy about the exam and worries about the class unity being damaged by an expulsion.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Listens as Ichinose assures the class no one will be expelled.<span class=\"pg\">p.252–253<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11-p14-1","v":"y1v11","y":1,"o":13,"k":"spoken","w":"chabashira-sae mashima-tomonari tsukishiro hoshinomiya-chie","q":"hoshinomiya chie ch 1  after the staff meeting watches as mashima challenges acting director tsukishiro in the staff meeting  talks with chabashira and mashima in the hallway  saying it is depressing that someone will be expelled  suggests tsukishiro may be trying to remove teachers who oppose him  teases chabashira about closing the gap and presses her about reaching class a  insists with chabashira that she has not brought personal feelings into the exams  after chabashira leaves  tells mashima she has gotten over the past but chabashira has not  says she has ichinose on her side and will not go easy on chabashira if class c gets close  talks with her about the exam and their rivalry  talks with him after the meeting  suspects his actions may target opposing teachers   it s depressing  isn t it  we have to announce an exam where someone s gonna get expelled   i wonder who s gonna disappear   you mean  overriding the expulsion with twenty million points  right   well  you re not alone on that  sae chan  he just popped up out of nowhere and  like  started doing whatever super unreasonable thing he wanted  didn t he   no way  sae chan  you re not fantasizing that your class might make it all the way to class a  are you   of course not  right  sae chan   don t lump me in with her  mashima kun  i ve already gotten over any lingering attachments i had  but that girl hasn t changed at all since back then  she ll never be able to move past her days as a student  that s why she s still stuck up on that good for nothing first love of hers  but she would never admit to that   you may be right  but i m not too worried since i have ichinose san on my side  besides   if they seem like they re getting close to reaching us  i ll pummel them back down myself","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11-p14-1\"><h3><span class=\"ttl\">Ch.1: After the staff meeting<\/span><span class=\"meta\">Y1V11 · p.14–26<\/span><\/h3><p class=\"setup\">Watches as Mashima challenges Acting Director Tsukishiro in the staff meeting. Talks with Chabashira and Mashima in the hallway, saying it is depressing that someone will be expelled. Suggests Tsukishiro may be trying to remove teachers who oppose him. Teases Chabashira about closing the gap and presses her about reaching Class A. Insists with Chabashira that she has not brought personal feelings into the exams. After Chabashira leaves, tells Mashima she has gotten over the past but Chabashira has not. Says she has Ichinose on her side and will not go easy on Chabashira if Class C gets close.<\/p><p class=\"with\">with <a href=\"chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"mashima-tomonari.html\">Mashima Tomonari<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It’s depressing, isn’t it? We have to announce an exam where someone’s gonna get expelled.”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\">“I wonder who’s gonna disappear…”<span class=\"pg\">p.21<\/span><\/li><li class=\"q spoken\">“You mean, overriding the expulsion with twenty million points, right?”<span class=\"pg\">p.22<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Talks with her about the exam and their rivalry.<span class=\"pg\">p.21–26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Mashima Tomonari<\/b> Talks with him after the meeting.<span class=\"pg\">p.21–26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Suspects his actions may target opposing teachers.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, you’re not alone on that, Sae-chan. He just popped up out of nowhere and, like, started doing whatever super unreasonable thing he wanted, didn’t he?”<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No way… Sae-chan, you’re not fantasizing that your class might make it all the way to Class A, are you?”<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Of course not. Right, Sae-chan?”<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t lump me in with her, Mashima-kun. I’ve already gotten over any lingering attachments I had. But that girl hasn’t changed at all since back then. She’ll never be able to move past her days as a student. That’s why she’s still stuck up on that good-for-nothing first love of hers, but she would never admit to that.”<span class=\"pg\">p.25<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You may be right, but I’m not too worried since I have Ichinose-san on my side. Besides…”<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If they seem like they’re getting close to reaching us, I’ll pummel them back down myself.”<span class=\"pg\">p.26<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p67-1\">→ After: Ch.3: Commanders’ meeting<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11-p67-1","v":"y1v11","y":1,"o":13,"k":"","w":"ichinose-honami hoshinomiya-chie","q":"hoshinomiya chie ch 3  commanders  meeting attends the commanders  meeting and reacts playfully with ichinose during the interface demonstration  jokes with her during the explanation","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11-p67-1\"><h3><span class=\"ttl\">Ch.3: Commanders’ meeting<\/span><span class=\"meta\">Y1V11 · p.67<\/span><\/h3><p class=\"setup\">Attends the commanders’ meeting and reacts playfully with Ichinose during the interface demonstration.<\/p><p class=\"with\">with <a href=\"ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Jokes with her during the explanation.<span class=\"pg\">p.67<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p14-1\">← Before: Ch.1: After the staff meeting<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p159-1\">→ After: Ch.4: Talking with Ayanokōji before school<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11-p159-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka chabashira-sae sakayanagi-arisu hoshinomiya-chie","q":"hoshinomiya chie ch 4  talking with ayanokoji before school calls out cheerfully to ayanokoji on the way to school and stops him to talk  asks about his relationship status and teases him while holding his hand  tells him the co ed dorm environment is ideal for romance and complains about boys and girls living in the same dormitory  shares a story about company room sharing to argue that single rooms encourage relationships  asks ayanokoji about dating across rival classes and says drama would make competition more exciting  stops the conversation when chabashira arrives and teases her  remarks that the special exam will show what ayanokoji can do against sakayanagi  approaches and talks with him on the way to school  teases her when she intervenes  mentions her as ayanokoji s opponent in the special exam","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11-p159-1\"><h3><span class=\"ttl\">Ch.4: Talking with Ayanokōji before school<\/span><span class=\"meta\">Y1V11 · p.159–168<\/span><\/h3><p class=\"setup\">Calls out cheerfully to Ayanokōji on the way to school and stops him to talk. Asks about his relationship status and teases him while holding his hand. Tells him the co-ed dorm environment is ideal for romance and complains about boys and girls living in the same dormitory. Shares a story about company room sharing to argue that single rooms encourage relationships. Asks Ayanokōji about dating across rival classes and says drama would make competition more exciting. Stops the conversation when Chabashira arrives and teases her. Remarks that the special exam will show what Ayanokōji can do against Sakayanagi.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"chabashira-sae.html\">Chabashira Sae<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Approaches and talks with him on the way to school.<span class=\"pg\">p.159–168<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Teases her when she intervenes.<span class=\"pg\">p.167–168<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Mentions her as Ayanokōji’s opponent in the special exam.<span class=\"pg\">p.168<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p67-1\">← Before: Ch.3: Commanders’ meeting<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p328-1\">→ After: Ch.7: Proctoring the exam<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11-p328-1","v":"y1v11","y":1,"o":13,"k":"","w":"hoshinomiya-chie","q":"hoshinomiya chie ch 7  proctoring the exam helps facilitate the special exam for class a and class c in the multipurpose room  prompts ayanokoji and sakayanagi to take their seats as the exam begins  comments on the matchup and is reprimanded for speaking out of turn  reacts in amazement at the difficulty of the flash mental arithmetic questions","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11-p328-1\"><h3><span class=\"ttl\">Ch.7: Proctoring the exam<\/span><span class=\"meta\">Y1V11 · p.328–362<\/span><\/h3><p class=\"setup\">Helps facilitate the special exam for Class A and Class C in the multipurpose room. Prompts Ayanokōji and Sakayanagi to take their seats as the exam begins. Comments on the matchup and is reprimanded for speaking out of turn. Reacts in amazement at the difficulty of the Flash Mental Arithmetic questions.<\/p><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p159-1\">← Before: Ch.4: Talking with Ayanokōji before school<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p332-1\">→ After: Ch.7: Proctoring the exam<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11-p332-1","v":"y1v11","y":1,"o":13,"k":"spoken","w":"sakayanagi-arisu hoshinomiya-chie","q":"hoshinomiya chie ch 7  proctoring the exam tells the commanders to take a seat   okaaay  the exam will begin any second now  please take a seat  says it is a shame ayanokoji faces sakayanagi   anywho  ayanokoji kun  it sure is a shame that you re gonna haveta go up against somebody like sakayanagi san  calls sakayanagi merciless   uwaa  sakayanagi san is soooo merciless  proctors the exam","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11-p332-1\"><h3><span class=\"ttl\">Ch.7: Proctoring the exam<\/span><span class=\"meta\">Y1V11 · p.332, 334–335, 338<\/span><\/h3><p class=\"setup\">Tells the commanders to take a seat. Says it is a shame Ayanokōji faces Sakayanagi. Calls Sakayanagi merciless.<\/p><p class=\"with\">with <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Okaaay, the exam will begin any second now~ Please take a seat~”<span class=\"pg\">p.332<\/span><\/li><li class=\"q spoken\">“Anywho, Ayanokōji-kun~ It sure is a shame that you’re gonna haveta go up against somebody like Sakayanagi-san.”<span class=\"pg\">p.334<\/span><\/li><li class=\"q spoken\">“Uwaa~ Sakayanagi-san is soooo merciless!”<span class=\"pg\">p.335<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Proctors the exam.<span class=\"pg\">p.334–335<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p328-1\">← Before: Ch.7: Proctoring the exam<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p403-1\">→ After: Epilogue: Proctoring the final event<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11-p403-1","v":"y1v11","y":1,"o":13,"k":"","w":"ayanokouji-kiyotaka sakagami-kazuma tsukishiro hoshinomiya-chie","q":"hoshinomiya chie epilogue  proctoring the final event offers water to the commanders before the chess event and observes the tense atmosphere  reacts in awe at the high level of the commander chess battle  consoles ayanokoji after class c s loss and remarks on the abilities he displayed  quietly warns ayanokoji that she may come to hate him if he becomes an enemy  helps with cleanup after being instructed by tsukishiro and sakagami  observes him during the exam and comments on his abilities afterward  proctors and cleans up alongside him  follows his instruction to leave and let staff handle cleanup","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11-p403-1\"><h3><span class=\"ttl\">Epilogue: Proctoring the final event<\/span><span class=\"meta\">Y1V11 · p.403–432<\/span><\/h3><p class=\"setup\">Offers water to the commanders before the chess event and observes the tense atmosphere. Reacts in awe at the high level of the commander chess battle. Consoles Ayanokōji after Class C’s loss and remarks on the abilities he displayed. Quietly warns Ayanokōji that she may come to hate him if he becomes an enemy. Helps with cleanup after being instructed by Tsukishiro and Sakagami.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"tsukishiro.html\">Tsukishiro<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Observes him during the exam and comments on his abilities afterward.<span class=\"pg\">p.403–431<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">sakagami-kazuma<\/b> Proctors and cleans up alongside him.<span class=\"pg\">p.403–432<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Follows his instruction to leave and let staff handle cleanup.<span class=\"pg\">p.432<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p332-1\">← Before: Ch.7: Proctoring the exam<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p430-1\">→ After: Epilogue: After the exam<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11-p430-1","v":"y1v11","y":1,"o":13,"k":"spoken","w":"sakagami hoshinomiya-chie","q":"hoshinomiya chie epilogue  after the exam asks whether he hid his abilities   the heck  does this mean you ve been hiding your abilities until now  announces the exam is over   the exam is over  students  please leave the room as soon as possible  says the students are lucky to go home   the students are so lucky  aren t they  getting to go back home and all  cleans up with him","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11-p430-1\"><h3><span class=\"ttl\">Epilogue: After the exam<\/span><span class=\"meta\">Y1V11 · p.430–431<\/span><\/h3><p class=\"setup\">Asks whether he hid his abilities. Announces the exam is over. Says the students are lucky to go home.<\/p><p class=\"with\">with <a href=\"sakagami.html\">Sakagami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“The heck? Does this mean you’ve been hiding your abilities until now?”<span class=\"pg\">p.430<\/span><\/li><li class=\"q spoken\">“The exam is over. Students, please leave the room as soon as possible.”<span class=\"pg\">p.431<\/span><\/li><li class=\"q spoken\">“The students are so lucky, aren’t they? Getting to go back home and all.”<span class=\"pg\">p.431<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakagami<\/b> Cleans up with him.<span class=\"pg\">p.431<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hoshinomiya-chie-y1v11-p403-1\">← Before: Epilogue: Proctoring the final event<\/button><\/div><\/article>"},{"i":"sc-hoshinomiya-chie-y1v11_5-p47-1","v":"y1v11.5","y":1,"o":14,"k":"","w":"tsukishiro sakayanagi-arisu ayanokouji-kiyotaka hoshinomiya-chie","q":"hoshinomiya chie ch 1  chess exam meeting participates in the meeting with ayanokoji  sakayanagi  tsukishiro  and other teachers concerning the chess exam  hears sakayanagi claim that ayanokoji was the original winner of the chess game and that the process was manipulated  takes part in the teachers  response as the issue of acting director tsukishiro s interference is pressed  confronts the acting director over exam interference  hears her accusation regarding the chess exam  present in the meeting involving his exam","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y1v11_5-p47-1\"><h3><span class=\"ttl\">Ch.1: Chess exam meeting<\/span><span class=\"meta\">Y1V11.5 · p.47–87<\/span><\/h3><p class=\"setup\">Participates in the meeting with Ayanokōji, Sakayanagi, Tsukishiro, and other teachers concerning the chess exam. Hears Sakayanagi claim that Ayanokōji was the original winner of the chess game and that the process was manipulated. Takes part in the teachers’ response as the issue of Acting Director Tsukishiro’s interference is pressed.<\/p><p class=\"with\">with <a href=\"tsukishiro.html\">Tsukishiro<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tsukishiro<\/b> Confronts the acting director over exam interference.<span class=\"pg\">p.47–87<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Hears her accusation regarding the chess exam.<span class=\"pg\">p.47–87<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Present in the meeting involving his exam.<span class=\"pg\">p.47–87<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hoshinomiya-chie-y2v1-p344-1","v":"y2v1","y":2,"o":16,"k":"","w":"hoshinomiya-chie","q":"hoshinomiya chie epilogue  mention mentioned in passing","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y2v1-p344-1\"><h3><span class=\"ttl\">Epilogue: Mention<\/span><span class=\"meta\">Y2V1 · p.344<\/span><\/h3><p class=\"setup\">Mentioned in passing.<\/p><\/article>"},{"i":"sc-hoshinomiya-chie-y2v12_5-p8-1","v":"y2v12.5","y":2,"o":32,"k":"","w":"ayanokouji-kiyotaka hoshinomiya-chie","q":"hoshinomiya chie prologue  ch 4  epilogue mentioned appears in prologue  ch 4  epilogue  appears in this volume","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y2v12_5-p8-1\"><h3><span class=\"ttl\">Prologue, Ch.4, Epilogue<\/span><span class=\"meta\">Y2V12.5 · p.8-10, 58-76, 200-202<\/span><\/h3><p class=\"setup\">Mentioned/appears in Prologue, Ch.4, Epilogue.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Appears in this volume.<span class=\"pg\">p.8-10, 58-76, 200-202<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hoshinomiya-chie-y3v1-p10-1","v":"y3v1","y":3,"o":33,"k":"","w":"hoshinomiya-chie","q":"hoshinomiya chie full volume appears in this volume","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y3v1-p10-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y3V1 · p.10-287<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-hoshinomiya-chie-y3v2-p10-1","v":"y3v2","y":3,"o":34,"k":"","w":"hoshinomiya-chie","q":"hoshinomiya chie full volume appears in this volume","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y3v2-p10-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y3V2 · p.10-263<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"},{"i":"sc-hoshinomiya-chie-y3v3-p12-1","v":"y3v3","y":3,"o":35,"k":"","w":"hoshinomiya-chie","q":"hoshinomiya chie full volume appears in this volume","h":"<article class=\"card\" id=\"sc-hoshinomiya-chie-y3v3-p12-1\"><h3><span class=\"ttl\">Full volume<\/span><span class=\"meta\">Y3V3 · p.12-256<\/span><\/h3><p class=\"setup\">Appears in this volume.<\/p><\/article>"}];
